 assert.equal(entry.path,name);
 const source=measure('source-pack/'+name);
 assert.equal(entry.source_bytes,source.bytes);
 assert.equal(entry.source_sha256,source.sha256);
 assert.ok(Number.isInteger(entry.source_bytes));
 assert.match(entry.source_sha256,/"'^[0-9a-f]{64}$/);
 const stagedPath='"'staged-pack/'+name;
 let status;
 if(fs.existsSync(stagedPath)){
  actualCounts.present_files++;
  const staged=measure(stagedPath);
  assert.equal(entry.staged_bytes,staged.bytes);
  assert.equal(entry.staged_sha256,staged.sha256);
  assert.ok(Number.isInteger(entry.staged_bytes));
  assert.match(entry.staged_sha256,/"'^[0-9a-f]{64}$/);
  const equal=fs.readFileSync('"'source-pack/'+name).equals(fs.readFileSync(stagedPath));
  assert.equal(equal,source.bytes===staged.bytes && source.sha256===staged.sha256);
  status=equal?'matching':'mismatched';
 }else{
  assert.equal(entry.staged_bytes,null);
  assert.equal(entry.staged_sha256,null);
  status='missing';
 }
 assert.equal(entry.status,status);
 actualCounts[status+'_files']++;
}
assert.deepEqual(Object.keys(inventory.summary),Object.keys(actualCounts));
for(const value of Object.values(inventory.summary)) assert.ok(Number.isInteger(value));
assert.deepEqual(inventory.summary,actualCounts);
assert.deepEqual(inventory,expectedInventory);
